('1af14084-ea1e-4069-a576-cd4cdd43607e', 'b1ead201-ffaa-4ba3-886a-033f3a9c1dbe', 'phantomautodetailingservice@gmail.com', 'Phantom Auto Detailing', 'SENT', '2026-03-21 14:29:24.394+00', '19d10cd01d6baa53', '19d10cd01d6baa53', NULL, '0', 'c37cf571-3f60-49e9-acf9-6627a1b69627', 'nitekartstore@gmail.com', NULL, NULL, NULL, 'https://phantomautodetaili6.wixsite.com/phantom-auto-detaili', 'quick question about your ceramic coating page, Phantom Auto Detailing', 'Hey Phantom Auto Detailing,\n\nTook a look at your site. Your work is solid but the ceramic coating page isn''t doing it justice.\n\nI put together a sample page for detailing shops that actually gets people to book. Reviews up front, pricing visible, one tap to get in touch.\n\nWorth sending it over?\nDemGrow', NULL, '{}', '2026-03-21 13:52:29.818716+00', NULL),
