('875cc8f9-d80c-4f97-9d4b-f2709581a070', '5947e05f-d285-4de0-87ae-6cc29c4e8cbd', 'service@justrightautowichita.com', 'Just Right Auto Repair', 'REPLIED', '2026-03-26 15:39:02.086+00', '19d2acc8d5ba4a2a', '19d2acc8d5ba4a2a', '2026-03-27 12:23:55.044+00', '1', 'c8ac189d-a210-40f7-aed5-4a7bb4545f09', 'readex0033@gmail.com', NULL, NULL, NULL, 'https://www.justrightautowichita.com/', 'quick question about your ceramic coating page, Just Right Auto Repair', 'Hey Just Right Auto Repair,\n\nTook a look at your site. Your work is solid but the ceramic coating page isn''t doing it justice.\n\nI put together a sample page for detailing shops that actually gets people to book. Reviews up front, pricing visible, one tap to get in touch.\n\nWorth sending it over?\nDemGrow', NULL, '{}', '2026-03-26 14:28:03.280016+00', NULL)
